mapper.sql:
select
  sd.*,
  st.name tenant_name
from sys_dict sd
left join sys_tenant st on sd.tenant_id = st.id and st.deleted = 0
where sd.deleted = 0


    and sd.tenant_id = 0


    and (
      sd.tenant_id = #{tenantId}
      or (
        sd.tenant_id = 0
        and not exists (
          select 1
          from sys_dict tenant_sd
          where tenant_sd.deleted = 0
            and tenant_sd.tenant_id = #{tenantId}
            and tenant_sd.`key` = sd.`key`
        )
      )
    )




    and (
      sd.tenant_id = #{tenantId}
      or (
        sd.tenant_id = 0
        and sd.source_scope = 'PUBLIC_SYSTEM'
      )
    )



  and sd.source_scope = #{sourceScope}


  and (
    sd.name like concat('%', #{keyword}, '%')
    or sd.`key` like concat('%', #{keyword}, '%')
  )

order by sd.tenant_id desc, sd.created_time desc, sd.id desc
